import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and neighbor sets
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            row = adj[i]
            for j in range(n):
                if row[j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    neighbor_sets = [set(neigh) for neigh in adj_list]
    deg = [len(neighbor_sets[i]) for i in range(n)]

    # Validate coloring
    def is_valid(colors):
        for u in range(n):
            cu = colors[u]
            for v in neighbor_sets[u]:
                if colors[v] == cu:
                    return False
        return True

    # Greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in neighbor_sets[v]:
                c = colors[u]
                if c != -1:
                    used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
        return colors

    # DSATUR heuristic with incremental saturation update
    def dsatur():
        colors = [-1] * n
        saturated = [set() for _ in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = len(saturated[v])
                d = 0
                for u in neighbor_sets[v]:
                    if u in uncolored:
                        d += 1
                if sat > best_sat or (sat == best_sat and d > best_deg) or (sat == best_sat and d == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = d
                    best_v = v
            v = best_v
            used = [False] * (n + 1)
            for u in neighbor_sets[v]:
                c = colors[u]
                if c != -1:
                    used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
            uncolored.remove(v)
            for u in neighbor_sets[v]:
                if u in uncolored:
                    saturated[u].add(c)
        return colors

    # RLF heuristic with set operations and early exit for empty U
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbor_sets[x] & uncolored))
            S = [v]
            U = uncolored - {v}
            W = neighbor_sets[v] & U
            U -= W
            while U:
                best_u = -1
                best_w_nei = -1
                best_deg_u = float('inf')
                for u in U:
                    w_nei = len(neighbor_sets[u] & W)
                    deg_u = len(neighbor_sets[u] & U)
                    if w_nei > best_w_nei or (w_nei == best_w_nei and deg_u < best_deg_u) or \
                       (w_nei == best_w_nei and deg_u == best_deg_u and u < best_u):
                        best_w_nei = w_nei
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                new_W = neighbor_sets[u] & U
                W |= new_W
                U -= new_W
            for vertex in S:
                colors[vertex] = color
            uncolored -= S
            color += 1
        return colors

    # Welsh-Powell (largest first)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        return greedy_color(order)

    # Smallest-last ordering (degeneracy ordering) with bucket optimization
    def smallest_last():
        if n == 0:
            return []
        remaining = set(range(n))
        order = []
        deg_copy = deg[:]
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg_copy[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                buckets.extend([[] for _ in range(d - len(buckets) + 1)])
                buckets[d].append(v)
        ptr = 0
        while remaining:
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break
            while buckets[ptr] and buckets[ptr][-1] not in remaining:
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            for u in neighbor_sets[v]:
                if u in remaining:
                    old_d = deg_copy[u]
                    deg_copy[u] -= 1
                    new_d = deg_copy[u]
                    if new_d < len(buckets):
                        buckets[new_d].append(u)
                    else:
                        buckets.extend([[] for _ in range(new_d - len(buckets) + 1)])
                        buckets[new_d].append(u)
        order.reverse()
        return greedy_color(order)

    # Kempe chain local search with component caching and early termination
    def kempe_reduce(colors):
        if n == 0:
            return colors
        k = max(colors) + 1
        if k <= 1:
            return colors
        improved = True
        # Limit iterations to avoid worst-case slowdown
        for _ in range(10):  # Max 10 passes
            if not improved:
                break
            improved = False
            color_class = [v for v in range(n) if colors[v] == k-1]
            if not color_class:
                k -= 1
                continue
            for v in color_class:
                neighbor_colors = set()
                for u in neighbor_sets[v]:
                    c = colors[u]
                    if c != -1:
                        neighbor_colors.add(c)
                # Try direct recoloring first
                for c in range(k-1):
                    if c not in neighbor_colors:
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    if k-1 not in colors:
                        k -= 1
                    break
                # Try Kempe chain swaps
                for c in range(k-1):
                    # BFS to find the Kempe chain component for colors c and k-1 starting from v
                    comp = set()
                    stack = [v]
                    comp.add(v)
                    while stack:
                        x = stack.pop()
                        for y in neighbor_sets[x]:
                            if y not in comp and (colors[y] == c or colors[y] == k-1):
                                comp.add(y)
                                stack.append(y)
                    # Check if swapping is safe: no neighbor of v with color k-1 in the component
                    conflict = False
                    for u in neighbor_sets[v]:
                        if colors[u] == k-1 and u in comp:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap
                        for x in comp:
                            if colors[x] == c:
                                colors[x] = k-1
                            elif colors[x] == k-1:
                                colors[x] = c
                        improved = True
                        if k-1 not in colors:
                            k -= 1
                        break
                if improved:
                    break
            if not improved:
                break
        return colors

    # Generate initial candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(welsh_powell())
    candidates.append(smallest_last())

    # Select the valid candidate with the fewest colors
    best_colors = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = max(col) + 1 if n > 0 else 0
            if k < best_k:
                best_k = k
                best_colors = col

    # Fallback: if none valid (should not happen), use greedy in order 0..n-1
    if best_colors is None:
        best_colors = greedy_color(list(range(n)))

    # Apply Kempe chain local search to try to reduce further
    best_colors = kempe_reduce(best_colors)

    return best_colors

