import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        neighbors = [set(lst) for lst in adj]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: Welsh-Powell ordering (degree descending)
    def welsh_powell_order():
        return sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)

    # Helper: DSATUR ordering with refined tie-breaking (max sat, max deg in uncolored, min index)
    def dsatur_order():
        uncolored = set(range(n))
        color = [-1] * n
        sat = [0] * n
        order = []
        while uncolored:
            v = max(uncolored, key=lambda x: (sat[x],
                                             len([u for u in neighbors[x] if u in uncolored]),
                                             -x))
            order.append(v)
            uncolored.remove(v)
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            for u in neighbors[v]:
                if u in uncolored and not used[c]:
                    sat[u] += 1
        return order

    # Helper: RLF (Recursive Largest First) with optimized independent set extraction
    def rlf_coloring():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            S = set()
            v = max(uncolored, key=lambda x: (len([u for u in neighbors[x] if u in uncolored]), -x))
            S.add(v)
            uncolored.remove(v)
            U = {u for u in uncolored if all(u not in neighbors[w] for w in S)}
            W = uncolored - U
            while U:
                u = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]),
                                         len([w for w in neighbors[x] if w in U]),
                                         -x))
                S.add(u)
                U.remove(u)
                for w in list(neighbors[u]):
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for v in S:
                color[v] = c
            uncolored = W
            c += 1
        return color

    # Helper: degeneracy ordering (smallest-last)
    def degeneracy_order():
        remaining = set(range(n))
        peel_order = []
        curr_degree = [len(neighbors[v]) for v in range(n)]
        while remaining:
            v = min(remaining, key=lambda x: (curr_degree[x], x))
            peel_order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    curr_degree[u] -= 1
        return list(reversed(peel_order))

    # Try multiple orderings and pick the best (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')

    orderings = [
        ("Welsh-Powell", welsh_powell_order()),
        ("DSATUR", dsatur_order()),
        ("Degeneracy", degeneracy_order())
    ]

    for name, order in orderings:
        coloring = greedy_color(order)
        num_colors = max(coloring) + 1 if n > 0 else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_coloring = coloring
        if best_num_colors == 1:
            break

    rlf_coloring_res = rlf_coloring()
    num_colors_rlf = max(rlf_coloring_res) + 1 if n > 0 else 0
    if num_colors_rlf < best_num_colors:
        best_num_colors = num_colors_rlf
        best_coloring = rlf_coloring_res

    # Local search: Kempe chain refinement with optimized elimination
    def kempe_chain(coloring, a, b, v):
        if coloring[v] not in (a, b):
            return set()
        stack = [v]
        visited = set([v])
        while stack:
            u = stack.pop()
            for w in neighbors[u]:
                if coloring[w] in (a, b) and w not in visited:
                    visited.add(w)
                    stack.append(w)
        return visited

    def try_kempe_reduction(coloring):
        max_color = max(coloring) if n > 0 else -1
        if max_color <= 0:
            return coloring
        vertices_max = [i for i in range(n) if coloring[i] == max_color]
        random.shuffle(vertices_max)
        for v in vertices_max:
            used = [False] * (max_color + 1)
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            for c in range(max_color):
                if not used[c]:
                    coloring[v] = c
                    return coloring
            for c in range(max_color):
                if used[c]:
                    chain = kempe_chain(coloring, c, max_color, v)
                    safe = True
                    for u in chain:
                        if coloring[u] == c:
                            for w in neighbors[u]:
                                if w not in chain and coloring[w] == max_color:
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        for u in chain:
                            if coloring[u] == c:
                                coloring[u] = max_color
                            else:
                                coloring[u] = c
                        return coloring
        return None

    current = best_coloring[:]
    for _ in range(30):
        new_coloring = try_kempe_reduction(current[:])
        if new_coloring is None:
            break
        current = new_coloring
        num_colors = max(current) + 1 if n > 0 else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_coloring = current[:]

    return best_coloring
